import datetime

def next_business_day(date_str: str, holidays: list[str]) -> str:
    current = datetime.date.fromisoformat(date_str) + datetime.timedelta(days=1)
    while True:
        if current.weekday() < 5:
            if current.isoformat() not in holidays:
                return current.isoformat()
        current += datetime.timedelta(days=1)
