def parse_csv_line(line: str) -> list[str]:
    result = []
    current = ''
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        if not in_quotes and line[i] == ',':
            result.append(current)
            current = ''
            i += 1
        else:
            c = line[i]
            if c == '"':
                if in_quotes:
                    if i + 1 < n and line[i + 1] == '"':
                        current += '"'
                        i += 2
                    else:
                        in_quotes = False
                        i += 1
                else:
                    in_quotes = True
                    i += 1
            else:
                current += c
                i += 1
    result.append(current)
    return result
