def parse_csv_line(line: str) -> list[str]:
    current_field = []
    fields = []
    i = 0
    in_quotes = False
    while i < len(line):
        char = line[i]
        if in_quotes:
            if char == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    current_field.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                current_field.append(char)
                i += 1
        else:
            if char == '"':
                in_quotes = True
                i += 1
            elif char == ',':
                fields.append(''.join(current_field))
                current_field = []
                i += 1
            else:
                current_field.append(char)
                i += 1
    fields.append(''.join(current_field))
    return fields
