def parse_duration(s: str) -> int:
    stripped_s = ''.join(s.split())
    if not stripped_s:
        raise ValueError("Empty duration string")
    import re
    pattern = r'(\d+)([dhms])'
    matches = re.findall(pattern, stripped_s, flags=re.IGNORECASE)
    reconstructed = ''.join([m[0] + m[1] for m in matches])
    if reconstructed != stripped_s:
        raise ValueError("Invalid characters in duration string")
    units = [m[1].lower() for m in matches]
    seen = set()
    for u in units:
        if u in seen:
            raise ValueError("Duplicate unit in duration string")
        seen.add(u)
    total = 0
    for number, unit in matches:
        value = int(number)
        u = unit.lower()
        if u == 'd':
            total += value * 86400
        elif u == 'h':
            total += value * 3600
        elif u == 'm':
            total += value * 60
        elif u == 's':
            total += value
    return total
