def flatten(obj: dict, sep: str = ".") -> dict:
    def _flattener(o, p):
        if isinstance(o, dict):
            if not o:
                return [(p, o)] if p else []
            else:
                items = []
                for k, v in o.items():
                    new_p = f"{p}{sep}{k}" if p else k
                    items.extend(_flattener(v, new_p))
                return items
        elif isinstance(o, list):
            if not o:
                return [(p, o)] if p else []
            else:
                items = []
                for i, v in enumerate(o):
                    new_p = f"{p}{sep}{i}" if p else str(i)
                    items.extend(_flattener(v, new_p))
                return items
        else:
            return [(p, o)]

    items = _flattener(obj, '')
    return dict(items)
