def flatten(obj: dict, sep: str = ".") -> dict:
    result = {}
    for key, val in obj.items():
        if isinstance(val, dict):
            if val:
                for k, v in flatten(val, sep).items():
                    new_key = f"{key}{sep}{k}"
                    result[new_key] = v
            else:
                result[key] = val
        elif isinstance(val, list):
            if val:
                temp = {str(i): v for i, v in enumerate(val)}
                for k, v in flatten(temp, sep).items():
                    new_key = f"{key}{sep}{k}"
                    result[new_key] = v
            else:
                result[key] = val
        else:
            result[key] = val
    return result
