def to_roman(n: int) -> str:
    if not 1 <= n <= 3999:
        raise ValueError
    roman_numerals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    res = ''
    for value, symbol in roman_numerals:
        while n >= value:
            res += symbol
            n -= value
    return res

def from_roman(s: str) -> int:
    if not s:
        raise ValueError
    allowed = {'I', 'V', 'X', 'L', 'C', 'D', 'M'}
    for c in s:
        if c not in allowed:
            raise ValueError
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for c in reversed(s):
        curr = roman_values[c]
        if curr < prev:
            total -= curr
        else:
            total += curr
        prev = curr
    if not 1 <= total <= 3999:
        raise ValueError
    if to_roman(total) != s:
        raise ValueError
    return total
