def to_roman(n: int) -> str:
    if n < 1 or n > 3999:
        raise ValueError("Invalid Roman numeral")
    numerals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    res = ''
    for value, symbol in numerals:
        while n >= value:
            res += symbol
            n -= value
        if n == 0:
            break
    return res

def from_roman(s: str) -> int:
    value_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not s:
        raise ValueError("Empty string")
    for c in s:
        if c not in value_map:
            raise ValueError("Invalid character in Roman numeral")
    total = 0
    prev = 0
    for c in reversed(s):
        val = value_map[c]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val
    if to_roman(total) != s:
        raise ValueError("Non-canonical Roman numeral")
    return total
