def moving_average(xs, k):
    if k <= 0 or k > len(xs):
        raise ValueError("k must be greater than 0 and at most the length of xs")
    out = []
    for i in range(len(xs) - k + 1):
        out.append(sum(xs[i:i + k]) / k)
    return out
```

